def solve(g):
    cnt=Counter(c for r in g for c in r); bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in g]
    for r in out:
        mk=[j for j,c in enumerate(r) if c!=bg]
        if not mk: continue
        # longest consecutive run
        best=[]; cur=[]
        for j in range(len(r)):
            if r[j]==bg and cur:
                pass
            if cur and (j==len(cur)-1+1 and r[j]!=bg): cur.append(j)
            else:
                if len(cur)>len(best): best=cur[:]; cur=[j]
                elif not cur: cur=[j]
            cur=[j] if r[j]!=bg else []
        if len(cur)>len(best): best=cur
        if not best: continue
        last=max(best)
        for j in range(last+1,len(r)):
            if out[-1][j]==bg: out[-1][j]=1
    return out,bg
