def comps(g):
    g=np.array(g); H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; col=g[r][c]; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append((comp,col))
    return out

def f(g):
    comps_=[(c,col) for c,col in comps(g) if len(c)==1]
    out=[r[:] for r in g]
    for (r,c),_ in comps_: out[r][c]=1
    return out

