d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def solve(g, rule):
    g=np.array(g); H,W=g.shape
    bg=int(Counter(g.flatten()).most_common(1)[0][0])
    mask=(g!=bg).any(axis=1)
    segs=[]; cur=None
    for i,mv in enumerate(mask):
        if mv:
            if cur is None: cur=i
        else:
            if cur is not None: segs.append((cur,i)); cur=None
    if cur is not None: segs.append((cur,H))
    AL=[]
    for st,endp in segs:
        X=g[st:endp]
        if len(AL)>0 and X.shape[0]!=AL[0].shape[0]: continue
        # best (dy,dx) maximizing matches with A
        best=-1; bestp=None
        for dy in range(3):
            Xy=np.roll(X,dy,axis=0)
            for dx in range(W):
                s=int((np.roll(Xy,dx,axis=1)==AL[0]).sum())
                if s>best: best=s; bestp=(dy,dx)
        dy,dx=bestp
        AL.append(np.roll(np.roll(X,dy,axis=0),dx,axis=1))
    res=[]
    for r in range(3):
        row=[]
        for c in range(W):
            cc=Counter(int(AL[x][r,c]) for x in range(len(AL)))
            nm=max(cc.values())
            common=[v for v,n in cc.items() if n==nm]
            val = common[0] if (len(common)==1 or (rule=='uniq' and nm>=2)) else 1
            row.append(val)
        res.append(row)
    return res

