def solve(g):
    g=np.array(g); H,W=g.shape
    bg=int(Counter(g.flatten()).most_common(1)[0][0])
    # segments: maximal runs of rows starting with a non-bg row or continuing
    segs=[]; cur=None
    for i in range(H):
        has=any(g[i,c]!=bg for c in range(W))
        if has:
            if cur is None: cur=i
        else:
            if cur is not None: segs.append((cur,i)); cur=None
    if cur is not None: segs.append((cur,H))
    AL=[]
    for st,endp in segs:
        X=g[st:endp]
        if len(AL)>0 and X.shape[0]!=AL[0].shape[0]: continue
        AH,AW=AL[0].shape
        best=max(range(AH),key=lambda dy:min(int(((np.roll(X,dy,axis=0)==AL[0]).sum()))) )
        AL.append(np.roll(X,best,axis=0))
    res=[[0]*W for _ in range(AH)]
    for r in range(AH):
        for c in range(AW):
            cc=Counter(int(AL[x][r,c]) for x in range(len(AL)))
            nm=max(cc.values())
            common=[v for v,n in cc.items() if n==nm]
            res[r][c]=common[0] if len(common)>=2 else 1
    return res

